func sourceLocation(s config.SourceEntry) string {
	switch s.Type {
	case "ast":
		return s.Path
	case "git", "repo":
		if s.URL != "" {
			return s.URL
		}
		return s.Path
	case "docs", "config", "image", "video", "audio":
		return strings.Join(s.Paths, ", ")
	case "url":
		if len(s.URLs) > 0 {
			return s.URLs[0]
		}
	}
	return ""
}

