func detectLanguage() string {
	manifests := map[string]string{
		"go.mod":       "go",
		"package.json": "typescript",
		"Cargo.toml":   "rust",
		"pom.xml":      "java",
		"build.gradle": "java",
	}
	for file, lang := range manifests {
		if _, err := os.Stat(file); err == nil {
			return lang
		}
	}
	return ""
}

